d DrawArc(Point start, Point offset, int pensize, int doubled){	Rect r;		/*PenSize(pensize, pensize);*/	offset.v *= pensize;	offset.h *= pensize;	if (offset.v == 0) {		MoveTo(start.h, start.v);		Line(offset.h, offset.v);				if (doubled) {			MoveTo (start.h, start.v - pensize * doubleOffset);			Line (offset.h, offset.v);		}	} else {		r.left = start.h;		r.right = start.h + offset.h + pensize;		if (offset.v > 0) {			r.top = start.v - offset.v - pensize;			r.bottom = start.v + offset.v + pensize;		} else {			r.top = start.v + offset.v;			r.bottom = start.v - offset.v + 2 * pensize;		}		FrameArc(&r, -90, offset.v > 0 ? -180 : 180);				if (doubled) {			InsetRect (&r, pensize * doubleOffset, pensize * doubleOffset);			FrameArc (&r, -90, offset.v > 0 ? -180 : 180);		}	}}